// NTSC Lite - simplified composite simulation, stack-safe
#include <metal_stdlib>
using namespace metal;

struct Uniforms {
    float4x4 MVP;
    float4 OutputSize;
    float4 SourceSize;
    float4 OriginalSize;
    uint   FrameCount;
    float  sharpness;     // 0..1
    float  bleed;         // 0..1 horizontal color bleed
    float  hue_shift;     // -1..1
    float  saturation;    // 0..2
    float  gamma;         // 0.5..3
};

struct VSIn { float4 pos [[attribute(0)]]; float2 uv [[attribute(1)]]; };
struct VSOut { float4 pos [[position]]; float2 uv; };

vertex VSOut main0(VSIn in [[stage_in]], constant Uniforms &u [[buffer(0)]]) {
    VSOut o; o.pos = u.MVP * in.pos; o.uv = in.uv; return o;
}

static inline float3 rgb2yiq(float3 c){
    float Y = dot(c, float3(0.299, 0.587, 0.114));
    float I = dot(c, float3(0.596, -0.274, -0.322));
    float Q = dot(c, float3(0.211, -0.523, 0.312));
    return float3(Y,I,Q);
}
static inline float3 yiq2rgb(float3 y){
    float3 r = float3(1.0, 0.956, 0.621);
    float3 g = float3(1.0, -0.272, -0.647);
    float3 b = float3(1.0, -1.106, 1.703);
    return float3(
        y.x*r.x + y.y*r.y + y.z*r.z,
        y.x*g.x + y.y*g.y + y.z*g.z,
        y.x*b.x + y.y*b.y + y.z*b.z
    );
}

fragment float4 fragment_main(
    VSOut in [[stage_in]],
    texture2d<float> src [[texture(0)]],
    constant Uniforms &u [[buffer(0)]]
){
    constexpr sampler smp(mag_filter::linear, min_filter::linear, address::clamp_to_edge);
    float2 uv = in.uv;

    // Horizontal pre-blur for color bleed
    float px = 1.0 / u.OutputSize.x;
    float3 c0 = src.sample(smp, uv - float2(2.0*px,0)).rgb;
    float3 c1 = src.sample(smp, uv - float2(1.0*px,0)).rgb;
    float3 c2 = src.sample(smp, uv).rgb;
    float3 c3 = src.sample(smp, uv + float2(1.0*px,0)).rgb;
    float3 c4 = src.sample(smp, uv + float2(2.0*px,0)).rgb;

    float3 blur = (c0 + 4.0*c1 + 6.0*c2 + 4.0*c3 + c4) / 16.0;
    float3 pre = mix(c2, blur, u.bleed);

    // Convert to YIQ and modulate chroma for sharpness/hue
    float3 yiq = rgb2yiq(pre);

    // Phase ripple to emulate subcarrier (cheap)
    float line = floor(uv.y * u.OutputSize.y);
    float phase = (line * 0.5 + float(u.FrameCount)*0.25);
    float cs = cos(phase * 0.25 + u.hue_shift*3.14159);
    float sn = sin(phase * 0.25 + u.hue_shift*3.14159);

    float I = yiq.y * cs - yiq.z * sn;
    float Q = yiq.y * sn + yiq.z * cs;

    I *= mix(0.6, 1.1, u.sharpness);
    Q *= mix(0.6, 1.1, u.sharpness);

    float3 outRGB = yiq2rgb(float3(yiq.x, I, Q));

    // Saturation and gamma
    float l = dot(outRGB, float3(0.299,0.587,0.114));
    outRGB = mix(float3(l), outRGB, u.saturation);
    outRGB = pow(max(outRGB, 0.0), float3(1.0/max(u.gamma,0.001)));

    return float4(saturate(outRGB), 1.0);
}

